import {behaviorOptions,responseLabels} from './behaviors.js';
import {bank, questionsFor, answeredCount} from './engine.js';
// Reuse the already translated shared interface; author content comes ONLY from bank.json.
import catalog from '../translations.json' with {type:'json'};
const escape = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function common(key, language) {
  if (language === 'en') return key;
  if (!catalog[key]?.[language]) throw new Error('MISSING_SHARED_TRANSLATION: '+key+'.'+language);
  return catalog[key][language];
}
export function progress(state, current = state.index + 1) {
  return bank.uiText.progress[state.language].replace('{current}', String(current)).replace('{total}', '12');
}
export function renderPreview(state, error = '', entering = false, options = {}) {
  const language = state.language, L = value => escape(value[language]), C = key => escape(common(key, language));
  const header = `<header class="site-header"><div class="shell header-inner"><a class="brand" href="/?intro=off"><span class="brand-mark" aria-hidden="true"><i></i><i></i><i></i></span><span>AI Career<br><b>Navigator</b></span></a><div class="header-actions"><span class="v3-version">${language==='zh-CN'?'职业探索':language==='ms'?'Penerokaan kerjaya':'Career exploration'}</span><label class="language-switch"><span class="sr-only">${C('Language')}</span><select id="v3-language" aria-label="${C('Language')}">${[['en','English'],['zh-CN','简体中文'],['ms','Bahasa Melayu']].map(([code, name]) => `<option value="${code}" ${code === language ? 'selected' : ''}>${name}</option>`).join('')}</select></label></div></div></header>`;
  const track = bank.tracks.find(track => track.id === state.trackId);
  const context = track ? L(track.label) : C(options.directionTitle || 'Choose a starting point.');
  const nav = `<div class="v3-page-top"><a class="text-button" href="/?intro=off">${C('← Back to home')}</a><span>${context}</span></div>`;
  const notice = options.hideNotice ? '' : `<p class="v3-notice">${C('Team Nexus · Domain 1 · Fictional profiles only')}</p>`;
  let body;
  if (state.screen === 'tracks') {
    body = `<section class="v3-entry"><span class="kicker">V3 · 12</span><h1>${C(options.directionTitle || 'Choose a starting point.')}</h1><p>${L(bank.uiText.intro)}</p>${notice}<div class="v3-tracks" role="group" aria-label="${C(options.directionTitle || 'Choose a starting point.')}">${bank.tracks.map((track, i) => `<button class="v3-track ${state.trackId === track.id ? 'is-selected' : ''}" data-track="${track.id}" aria-pressed="${state.trackId === track.id}"><span class="v3-track-index">${String(i + 1).padStart(2,'0')}</span><span>${L(track.label)}</span><span aria-hidden="true">↗</span></button>`).join('')}</div></section>`;
  } else if (state.screen === 'review') {
    body = `<section class="v3-review"><div class="v3-review-top"><div><span class="kicker">V3 · ${answeredCount(state)} / 12</span><h1 tabindex="-1" id="v3-heading">${C('Your profile')}</h1><p>${C('Check your answers and confirm the fictional profile.')}</p></div><button class="button secondary" data-v3-action="back">${L(bank.uiText.back)}</button></div><ol class="v3-review-list">${questionsFor(state.trackId).map((question, index) => `<li><div><span class="small-label">${L(bank.constructLabels[question.construct])}</span><h2>${index + 1}. ${L(question.statement)}</h2><p>${Array.isArray(state.answers[question.id]) ? escape(responseLabels(question,state.answers[question.id],language)) : state.answers[question.id] === null ? L(bank.uiText.unfamiliar) : `${state.answers[question.id]} · ${L(bank.scale.find(option => option.value === state.answers[question.id]).label)}`} </p></div><button class="text-button" data-v3-edit="${index}">${C('Edit your answers ↗')}</button></li>`).join('')}</ol><button class="text-button" data-v3-action="reset">${C('Start over')}</button></section>`;
  } else {
    const question = questionsFor(state.trackId)[state.index], selected = state.answers[question.id];
    body = `<section class="v3-question-page${entering ? ' is-entering' : ''}"><div class="v3-progress-label"><span>${L(bank.constructLabels[question.construct])}</span><span>${escape(progress(state))}</span></div><div class="v3-progress" role="progressbar" aria-label="${escape(progress(state))}" aria-valuemin="0" aria-valuemax="12" aria-valuenow="${answeredCount(state)}"><i style="width:${answeredCount(state) / 12 * 100}%"></i></div><article class="v3-question" data-question-id="${question.id}"><div class="v3-statement"><span class="kicker">${language==='zh-CN'?'任务背景':language==='ms'?'Konteks tugas':'Task context'}</span><p class="behavior-context">${L(question.statement)}</p><h1 id="v3-heading" tabindex="-1">${language==='zh-CN'?'关于这类任务，哪些情况符合你？':language==='ms'?'Bagi tugas ini, apakah yang menggambarkan anda?':'For this kind of work, what describes you?'}</h1><p id="v3-question-help">${language==='zh-CN'?'选择真实经历与偏好，而不是理想中的自己。':language==='ms'?'Pilih pengalaman dan keutamaan sebenar, bukan diri ideal anda.':'Choose actual experiences and preferences, rather than your ideal self.'}</p></div><fieldset class="v3-options" aria-labelledby="v3-heading" aria-describedby="v3-question-help"><legend class="sr-only">${L(question.statement)}</legend><p class="behavior-help">${language==='zh-CN'?'选择最多 3 项符合你的具体情况；最后一项与其他选项互斥。':language==='ms'?'Pilih sehingga 3 keadaan sebenar; pilihan terakhir tidak boleh digabungkan.':'Choose up to 3 real situations. The last option is exclusive.'}</p>${Number.isInteger(selected)?`<p class="behavior-history">${language==='zh-CN'?'已保留历史量表答案；选择下列行为会替换本题答案，不与历史分数比较。':language==='ms'?'Jawapan skala lama dikekalkan. Memilih tingkah laku menggantikannya tanpa perbandingan skor.':'Historical scale answer retained. Selecting a behavior replaces it; scores are not compared.'}</p>`:''}<div class="behavior-options">${behaviorOptions(question).map(option=>`<label class="behavior-option ${Array.isArray(selected)&&selected.includes(option.id)?'is-selected':''}"><input type="checkbox" name="v3-behavior" value="${option.id}" ${Array.isArray(selected)&&selected.includes(option.id)?'checked':''}><span class="behavior-check" aria-hidden="true">${Array.isArray(selected)&&selected.includes(option.id)?'✓':'+'}</span><span>${L(option.label)}</span></label>`).join('')}</div><label class="v3-unknown ${selected===null?'is-selected':''}"><input type="radio" name="v3-answer" value="unknown" ${selected===null?'checked':''}><span>${L(bank.uiText.unfamiliar)}</span></label></fieldset>${error ? `<p class="v3-error" role="alert">${C(error)}</p>` : ''}<div class="v3-question-actions"><button class="button secondary" data-v3-action="back">← ${L(bank.uiText.back)}</button><span>${answeredCount(state)} / 12</span><button class="button primary" data-v3-action="next">${L(bank.uiText.next)} ↗</button></div></article></section>`;
  }
  return `<div class="v3-app" lang="${language}">${header}<main class="shell v3-shell">${nav}${body}</main><footer class="v3-footer">${C('Your answers are safe in this tab.')}</footer></div>`;
}
